// Один файл, C++14 + SDL2. Без внешних ассетов: графика — примитивы, шрифт — зашитый массив глифов,
// звук — процедурный синтез.
// Сборка: g++ -std=c++14 -O2 -Wall -Wextra device_corp.cpp -o device_corp $(sdl2-config --cflags --libs)

